package com.logiplatform.model;

import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;

@Entity @Table(name="ocean_voyages") public class OceanVoyage { @Id @GeneratedValue UUID id; @Column(name="tenant_id",nullable=false,updatable=false) UUID tenantId; @Column(name="vessel_name",nullable=false) String vesselName; String imoNumber; @Column(name="voyage_number",nullable=false) String voyageNumber; String carrierName,serviceName,originPort,destinationPort; Instant etd,eta; String transshipmentPorts; @Column(nullable=false) String status="SCHEDULED"; BigDecimal capacityTeu; @Column(nullable=false) BigDecimal bookedTeu=BigDecimal.ZERO; Instant createdAt=Instant.now(),updatedAt=Instant.now(); protected OceanVoyage(){} public OceanVoyage(UUID t,String vessel,String imo,String voyage,String carrier,String service,String origin,String dest,Instant etd,Instant eta,BigDecimal cap){tenantId=t;vesselName=vessel;imoNumber=imo;voyageNumber=voyage;carrierName=carrier;serviceName=service;originPort=origin;destinationPort=dest;this.etd=etd;this.eta=eta;capacityTeu=cap;} public UUID getId(){return id;} public String getVesselName(){return vesselName;} public String getVoyageNumber(){return voyageNumber;} public String getCarrierName(){return carrierName;} public String getOriginPort(){return originPort;} public String getDestinationPort(){return destinationPort;} public Instant getEtd(){return etd;} public Instant getEta(){return eta;} public String getStatus(){return status;} public BigDecimal getCapacityTeu(){return capacityTeu;} public BigDecimal getBookedTeu(){return bookedTeu;} }
